import { cacheTag } from 'next/cache'

export type Post = {
  id: string
  title: string
  content: string
}

const posts: Post[] = []

export async function addPost(input: { title: string; content: string }) {
  const post: Post = {
    id: crypto.randomUUID(),
    title: input.title,
    content: input.content,
  }
  posts.unshift(post)
  return post
}

export async function getPosts() {
  'use cache'
  cacheTag('posts')
  return posts
}

